const numbers = [10, 20, 30];

let total = 0;

for (const n of numbers) {
  total = total + n;
}

function getTotal() {
  return total;
}

function countByStatus(items) {
  const result = { soldOut: 0, low: 0, enough: 0 };

  for (const item of items) {
    if (item.stock === 0) {
      result.soldOut += 1;
    } else if (item.stock < 10) {
      result.low += 1;
    } else {
      result.enough += 1;
    }
  }

  return result;
}
